    @Override // org.telegram.messenger.NotificationCenter.NotificationCenterDelegate
    public void didReceivedNotification(int i, int i2, Object... objArr) {
        MessageObject messageObject;
        TLRPC.User user;
        if (i == NotificationCenter.startSpoilers) {
            setSpoilersSuppressed(false);
            return;
        }
        if (i == NotificationCenter.stopSpoilers) {
            setSpoilersSuppressed(true);
            return;
        }
        if (i == NotificationCenter.userInfoDidLoad) {
            Long l = (Long) objArr[0];
            if (this.widePostsEmbeddedProfileAvatar && isWidePostsHeaderUser(l.longValue())) {
                if (shouldRebuildWidePostsProfileHeader()) {
                    refreshAuthorHeader();
                    return;
                } else {
                    setAvatar(this.currentMessageObject);
                    invalidate();
                    return;
                }
            }
            if (this.widePostsEmbeddedProfileAvatar || (user = this.currentUser) == null || user.id != l.longValue()) {
                return;
            }
            setAvatar(this.currentMessageObject);
            return;
        }
        if (i == NotificationCenter.emojiLoaded) {
            invalidate();
            return;
        }
        if (i == NotificationCenter.updateInterfaces) {
            if (i2 != this.currentAccount) {
                return;
            }
            int iIntValue = ((Integer) objArr[0]).intValue();
            if (shouldUpdateWidePostsProfilePlacement(iIntValue)) {
                refreshAuthorHeader();
                return;
            }
            if (shouldRebuildWidePostsProfileHeader()) {
                refreshAuthorHeader();
                return;
            }
            if (this.widePostsEmbeddedProfileAvatar || this.feedDisplayChannel != null) {
                if (((MessagesController.UPDATE_MASK_NAME | MessagesController.UPDATE_MASK_CHAT | MessagesController.UPDATE_MASK_CHAT_NAME | MessagesController.UPDATE_MASK_EMOJI_STATUS) & iIntValue) != 0) {
                    refreshAuthorHeader();
                    return;
                } else if (((MessagesController.UPDATE_MASK_AVATAR | MessagesController.UPDATE_MASK_CHAT_AVATAR) & iIntValue) != 0) {
                    setAvatar(this.currentMessageObject);
                    invalidate();
                    return;
                }
            }
            if ((iIntValue & MessagesController.UPDATE_MASK_STATUS) != 0 && isAvatarVisibleOutside() && ExteraConfig.getShowOnlineStatus()) {
                postInvalidateParentOnAnimation();
                return;
            }
            return;
        }
        if (i != NotificationCenter.didUpdatePremiumGiftStickers || (messageObject = this.currentMessageObject) == null) {
            return;
        }
        TLRPC.MessageMedia messageMedia = messageObject.messageOwner.media;
        if ((messageMedia instanceof TLRPC.TL_messageMediaGiveaway) || (messageMedia instanceof TLRPC.TL_messageMediaGiveawayResults)) {
            setMessageObject(messageObject, this.currentMessagesGroup, this.pinnedBottom, this.pinnedTop, this.firstInChat);
        }
    }

    public void setAvatar(MessageObject messageObject) {
        if (messageObject == null) {
            return;
        }
        if (this.isAvatarVisible) {
            if (this.widePostsEmbeddedProfileAvatar) {
                TLRPC.User widePostsProfileUser = getWidePostsProfileUser();
                if (widePostsProfileUser != null) {
                    TLRPC.UserProfilePhoto userProfilePhoto = widePostsProfileUser.photo;
                    this.currentPhoto = userProfilePhoto != null ? userProfilePhoto.photo_small : null;
                    this.avatarDrawable.setInfo(this.currentAccount, widePostsProfileUser);
                    this.avatarImage.setForUserOrChat(widePostsProfileUser, this.avatarDrawable, null, LiteMode.isEnabled(LiteMode.FLAGS_CHAT), 1, false);
                    return;
                }
                TLRPC.Chat widePostsProfileChat = getWidePostsProfileChat();
                if (widePostsProfileChat != null) {
                    TLRPC.ChatPhoto chatPhoto = widePostsProfileChat.photo;
                    this.currentPhoto = chatPhoto != null ? chatPhoto.photo_small : null;
                    this.avatarDrawable.setInfo(this.currentAccount, widePostsProfileChat);
                    this.avatarImage.setForUserOrChat(widePostsProfileChat, this.avatarDrawable);
                    return;
                }
                if (hasWidePostsProfilePeer()) {
                    this.currentPhoto = null;
                    this.avatarDrawable.setInfo(getWidePostsProfileDialogId(), null, null);
                    this.avatarImage.setImage(null, null, this.avatarDrawable, null, null, 0);
                    return;
                }
            }
            TLRPC.Chat chat = this.feedDisplayChannel;
            if (chat != null) {
                TLRPC.ChatPhoto chatPhoto2 = chat.photo;
                this.currentPhoto = chatPhoto2 != null ? chatPhoto2.photo_small : null;
                this.avatarDrawable.setInfo(this.currentAccount, chat);
                this.avatarImage.setForUserOrChat(this.feedDisplayChannel, this.avatarDrawable);
                return;
            }
            Drawable drawable = messageObject.customAvatarDrawable;
            if (drawable != null) {
                this.avatarImage.setImageBitmap(drawable);
                return;
            }
            TLRPC.User user = this.currentUser;
            if (user != null) {
                TLRPC.UserProfilePhoto userProfilePhoto2 = user.photo;
                if (userProfilePhoto2 != null) {
                    this.currentPhoto = userProfilePhoto2.photo_small;
                } else {
                    this.currentPhoto = null;
                }
                this.avatarDrawable.setInfo(this.currentAccount, user);
                this.avatarImage.setForUserOrChat(this.currentUser, this.avatarDrawable, null, LiteMode.isEnabled(LiteMode.FLAGS_CHAT), 1, false);
                return;
            }
            TLRPC.Chat chat2 = this.currentChat;
            if (chat2 != null) {
                TLRPC.ChatPhoto chatPhoto3 = chat2.photo;
                if (chatPhoto3 != null) {
                    this.currentPhoto = chatPhoto3.photo_small;
                } else {
                    this.currentPhoto = null;
                }
                if (chat2.signature_profiles && messageObject.getDialogId() != UserObject.REPLY_BOT) {
                    long peerDialogId = DialogObject.getPeerDialogId(messageObject.messageOwner.from_id);
                    int i = messageObject.currentAccount;
                    if (peerDialogId >= 0) {
                        TLRPC.User user2 = MessagesController.getInstance(i).getUser(Long.valueOf(peerDialogId));
                        this.avatarDrawable.setInfo(this.currentAccount, user2);
                        this.avatarImage.setForUserOrChat(user2, this.avatarDrawable);
                        return;
                    } else {
                        TLRPC.Chat chat3 = MessagesController.getInstance(i).getChat(Long.valueOf(-peerDialogId));
                        this.avatarDrawable.setInfo(this.currentAccount, chat3);
                        this.avatarImage.setForUserOrChat(chat3, this.avatarDrawable);
                        return;
                    }
                }
                this.avatarDrawable.setInfo(this.currentAccount, this.currentChat);
                this.avatarImage.setForUserOrChat(this.currentChat, this.avatarDrawable);
                return;
            }
            if (messageObject.isSponsored()) {
                this.currentPhoto = null;
                if (messageObject.searchType == 4) {
                    this.avatarDrawable.setAvatarType(1);
                    this.avatarDrawable.setCustomIcon(Theme.avatarDrawables[5]);
                    this.avatarImage.setImage(null, null, this.avatarDrawable, null, null, 0);
                    return;
                } else {
                    TLRPC.Photo photo = messageObject.sponsoredPhoto;
                    if (photo != null) {
                        this.avatarImage.setImage(ImageLocation.getForPhoto(FileLoader.getClosestPhotoSizeWithSize(photo.sizes, AndroidUtilities.dp(50.0f), false, null, true), messageObject.sponsoredPhoto), "50_50", this.avatarDrawable, null, null, 0);
                        return;
                    }
                    return;
                }
            }
            this.currentPhoto = null;
            this.avatarDrawable.setInfo(messageObject.getFromChatId(), null, null);
            this.avatarImage.setImage(null, null, this.avatarDrawable, null, null, 0);
            return;
        }
        this.currentPhoto = null;
    }

